// Pick users to nudge:
//  - status not 'closed' / 'customer'
//  - ai_enabled is TRUE (don't bother users a human is handling)
//  - last_message_at between 4h and 22h ago (stay inside FB 24h messaging window)
//  - followup_count < 2 (max 2 nudges per lead)
const rows = $input.all().map(i => i.json);
const now = Date.now();
const MIN_AGE = 4 * 60 * 60 * 1000;
const MAX_AGE = 22 * 60 * 60 * 1000;

const NUDGES = [
  // first follow-up (Banglish)
  'Apu, ekhono kichu jante chan? Amra ready achi help korte!',
  // second follow-up
  'Kichu confusion thakle bolun apu, ami answer dichhi - oder ti miss korben na!'
];

const out = [];
for (const r of rows) {
  if (!r || !r.psid) continue;
  const status = String(r.status || '').toLowerCase();
  if (status === 'closed' || status === 'customer') continue;

  const aiEnabled = String(r.ai_enabled || 'TRUE').toUpperCase();
  if (aiEnabled !== 'TRUE' && aiEnabled !== '1') continue;

  const last = r.last_message_at ? new Date(r.last_message_at).getTime() : 0;
  if (!last) continue;
  const age = now - last;
  if (age < MIN_AGE || age > MAX_AGE) continue;

  const count = Number(r.followup_count || 0);
  if (count >= NUDGES.length) continue;

  out.push({
    json: {
      psid: r.psid,
      name: r.name || '',
      status: r.status || 'lead',
      followup_count: count,
      next_followup_count: count + 1,
      message: NUDGES[count],
      now_iso: new Date().toISOString()
    }
  });
}
return out;
